"""Tests for the yarn.lock extractor.

Mirrors tests/test_extractors_pnpm.py: template contract, extract-level tests
for both formats, and the error contract. Every fixture is synthetic. Each gate
was measured against every real yarn.lock on a development estate first (156
files: v1 x111, Berry `__metadata.version` 10 x39, 8 x4, 6 x1, and one
comment-only test fixture) -- see docs/dependency-details.md.
"""
import pytest

from kospex.extractors.errors import UnreadableManifest
from kospex.extractors.yarn import _template, extract_yarn_lock

V1_HEADER = (
    "# THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.\n"
    "# yarn lockfile v1\n\n\n"
)

#: Shaped on the real files: unquoted and quoted keys, a scoped package, two
#: descriptors resolving to one entry, a nested dependencies section, an
#: optionalDependencies section, and an integrity line (the only unquoted value).
V1 = V1_HEADER + '''\
"@babel/code-frame@^7.0.0", "@babel/code-frame@^7.22.13":
  version "7.22.13"
  resolved "https://registry.yarnpkg.com/@babel/code-frame/-/code-frame-7.22.13.tgz#e3c1c099402598483b7a8c46a721d1038803755e"
  integrity sha512-XktuhWlJ5g+3TJXc5upd9Ks1HutSArik6jf2eAjYFyIOf4ej3RN+184cZbzDvbPnuTJIUhPKKJE3cIsYTiAT3w==
  dependencies:
    "@babel/highlight" "^7.22.13"
    chalk "^2.4.2"

lodash@^4.17.15, lodash@^4.17.21:
  version "4.17.21"
  resolved "https://registry.yarnpkg.com/lodash/-/lodash-4.17.21.tgz#679591c564c3bffaae8454cf0b3df370c3d6911c"
  integrity sha512-v2kDEe57lecTulaDIuNTPy3Ry4gLGJ6Z1O3vE1krgXZNrsQ+LFTGHVxVjcXPs17LhbZVGedAJv8XZ1tvj5FvSg==

chokidar@^3.5.3:
  version "3.5.3"
  resolved "https://registry.yarnpkg.com/chokidar/-/chokidar-3.5.3.tgz#1cf37c8707b932bd1af1ae22c0432e2acd1903bd"
  optionalDependencies:
    fsevents "~2.3.2"
'''


def _write(tmp_path, content, name="yarn.lock"):
    path = tmp_path / name
    path.write_text(content)
    return str(path)


def _write_bytes(tmp_path, raw, name="yarn.lock"):
    path = tmp_path / name
    path.write_bytes(raw)
    return str(path)


def _pairs(records):
    return sorted((r["package_name"], r["package_version"]) for r in records)


def _berry(entries, version=10):
    """A Berry lockfile around `entries` (YAML text for the package entries)."""
    return (
        "# This file is generated by running \"yarn install\" inside your project.\n"
        "# Manual changes might be lost - proceed with caution!\n\n"
        f"__metadata:\n  version: {version}\n  cacheKey: 10c0\n\n" + entries
    )


ROOT_WORKSPACE = '''\
"app@workspace:.":
  version: 0.0.0-use.local
  resolution: "app@workspace:."
  dependencies:
    lodash: "npm:^4.17.21"
  languageName: unknown
  linkType: soft
'''

LODASH = '''\
"lodash@npm:^4.17.15, lodash@npm:^4.17.21":
  version: 4.17.21
  resolution: "lodash@npm:4.17.21"
  checksum: 10c0/d8cbea072bb08655bb4c989da418994b073a608dffa608b09ac04b43a791b12aeae7cd7ad919aa4c925f33b48490b5cfe6c1f71d827956071dae2e7bb3a6b74
  languageName: node
  linkType: hard
'''


class TestTemplateContract:
    """The local record template must stay in sync with KospexDependencies."""

    def test_template_matches_get_package_template(self):
        from kospex_dependencies import KospexDependencies
        assert set(_template().keys()) == set(
            KospexDependencies().get_package_template().keys()
        )

    def test_advisory_columns_default_to_null_not_empty_string(self):
        """INTEGER columns: '' sorts above every integer in SQLite (#258)."""
        t = _template()
        assert t["advisories"] is None
        assert t["versions_behind"] is None


class TestV1:

    def test_every_entry_is_recorded_once(self, tmp_path):
        records = extract_yarn_lock(_write(tmp_path, V1))
        assert _pairs(records) == [
            ("@babel/code-frame", "7.22.13"),
            ("chokidar", "3.5.3"),
            ("lodash", "4.17.21"),
        ]
        assert all(r["ecosystem"] == "npm" for r in records)

    def test_nothing_is_claimed_that_the_format_does_not_state(self, tmp_path):
        """A lockfile is the hoisted install set, not the declared set, and v1
        has no dev or optional flag -- so every row is `resolved` and the
        install-state columns stay NULL, meaning "the format cannot say"."""
        from kospex_schema import REQ_TO_PACKAGE_USE
        for r in extract_yarn_lock(_write(tmp_path, V1)):
            assert r["requirements_type"] == "resolved"
            assert r["requirements_type"] in REQ_TO_PACKAGE_USE
            for column in ("is_dev", "is_optional", "runs_install_script", "declared_scope"):
                assert r[column] is None, column

    def test_header_only_file_is_genuinely_empty(self, tmp_path):
        """A project with no dependencies: read, and declares nothing."""
        assert extract_yarn_lock(_write(tmp_path, V1_HEADER)) == []

    def test_npm_alias_records_alias_and_target(self, tmp_path):
        """`foo@npm:bar@^1` installs bar as foo. Both are identities the file
        asserts -- the alias name is what the project declares, the target is
        what deps.dev knows -- so both are recorded, as the npm lockfile parser
        does."""
        content = V1_HEADER + '''\
"string-width-cjs@npm:string-width@^4.2.0":
  version "4.2.3"
  resolved "https://registry.yarnpkg.com/string-width/-/string-width-4.2.3.tgz#269c7117d27b05ad2e536830a8ec895ef9c6d010"
'''
        assert _pairs(extract_yarn_lock(_write(tmp_path, content))) == [
            ("string-width", "4.2.3"),
            ("string-width-cjs", "4.2.3"),
        ]

    def test_resolved_url_that_disagrees_is_recorded_too(self, tmp_path):
        """No field of a lockfile vouches for another. A key claiming one
        package while `resolved` fetches another must not hide the second."""
        content = V1_HEADER + '''\
left-pad@^1.0.0:
  version "1.3.0"
  resolved "https://registry.yarnpkg.com/evil-pkg/-/evil-pkg-6.6.6.tgz#abc"
'''
        assert _pairs(extract_yarn_lock(_write(tmp_path, content))) == [
            ("evil-pkg", "1.3.0"),
            ("evil-pkg", "6.6.6"),
            ("left-pad", "1.3.0"),
            ("left-pad", "6.6.6"),
        ]

    def test_mirror_url_does_not_change_identity(self, tmp_path):
        """A package fetched from a registry mirror is still that package."""
        content = V1_HEADER + '''\
lodash@^4.17.21:
  version "4.17.21"
  resolved "https://registry.npmmirror.com/lodash/-/lodash-4.17.21.tgz#679591c5"
'''
        assert _pairs(extract_yarn_lock(_write(tmp_path, content))) == [
            ("lodash", "4.17.21")]

    def test_local_link_and_file_entries_are_not_packages(self, tmp_path):
        """No registry identity: a local directory has nothing for deps.dev to
        answer about. Real ones carry a version but no `resolved` line."""
        content = V1_HEADER + '''\
"eslint-plugin-internal@link:./scripts/eslint-rules":
  version "0.0.0"
  uid ""

"@acme/worker@file:../worker":
  version "1.0.0"

lodash@^4.17.21:
  version "4.17.21"
  resolved "https://registry.yarnpkg.com/lodash/-/lodash-4.17.21.tgz#679591c5"
'''
        assert _pairs(extract_yarn_lock(_write(tmp_path, content))) == [
            ("lodash", "4.17.21")]

    def test_a_local_key_that_was_fetched_is_still_recorded(self, tmp_path):
        """Testing the key alone would let one edit hide a dependency: an entry
        that names a registry tarball was downloaded, whatever its key says."""
        content = V1_HEADER + '''\
"evil-pkg@link:./vendored":
  version "6.6.6"
  resolved "https://registry.yarnpkg.com/evil-pkg/-/evil-pkg-6.6.6.tgz#abc"
'''
        assert _pairs(extract_yarn_lock(_write(tmp_path, content))) == [
            ("evil-pkg", "6.6.6")]

    def test_git_hosted_entry_is_recorded_by_name(self, tmp_path):
        content = V1_HEADER + '''\
"leftpad@github:acme/leftpad#v1.3.0":
  version "1.3.0"
  resolved "https://codeload.github.com/acme/leftpad/tar.gz/0123abcd"
'''
        assert _pairs(extract_yarn_lock(_write(tmp_path, content))) == [
            ("leftpad", "1.3.0")]

    def test_utf8_bom_is_accepted(self, tmp_path):
        path = _write_bytes(tmp_path, b"\xef\xbb\xbf" + V1.encode())
        assert len(extract_yarn_lock(path)) == 3


class TestV1Unreadable:

    def test_line_outside_the_grammar_raises(self, tmp_path):
        """Measured: every line of 111 real v1 files fits the grammar. So a
        line that does not is a file this parser has not understood, and
        skipping it could skip a package."""
        with pytest.raises(UnreadableManifest, match="line 7"):
            extract_yarn_lock(_write(tmp_path, V1_HEADER + '''\
lodash@^4.17.21:
  version "4.17.21"
        resolved "https://registry.yarnpkg.com/lodash/-/lodash-4.17.21.tgz"
'''))

    def test_field_before_any_entry_raises(self, tmp_path):
        with pytest.raises(UnreadableManifest):
            extract_yarn_lock(_write(tmp_path, V1_HEADER + '  version "1.0.0"\n'))

    def test_bad_quoting_raises(self, tmp_path):
        with pytest.raises(UnreadableManifest):
            extract_yarn_lock(_write(tmp_path, V1_HEADER + 'lodash@^4:\n  version "4.17.21\n'))

    @pytest.mark.parametrize("key", [
        ',lodash@^4:',                 # empty descriptor first
        'lodash@^4,,lodash@^4.1:',     # empty descriptor between
        'lodash@^4, ,lodash@^4.1:',    # whitespace-only descriptor
        'lodash@^4, :',                # whitespace-only descriptor last
        '"lodash@^4"x:',               # junk after a quoted descriptor
        'lodash"@^4:',                 # quote inside an unquoted descriptor
        '"lodash@^4:',                 # unclosed quote
    ])
    def test_malformed_entry_key_raises(self, tmp_path, key):
        with pytest.raises(UnreadableManifest, match="unreadable entry key"):
            extract_yarn_lock(_write(tmp_path, V1_HEADER + key + '\n  version "4.17.21"\n'))

    def test_long_entry_key_is_rejected_in_linear_time(self, tmp_path):
        """CWE-1333. A regex splitting the key on `[^,"]+\\s*(?:,|$)` backtracked
        quadratically on whitespace: a 16,000-character key took over a second,
        and one 1 MB line in a committed lockfile would stall the parse for
        hours. The scanner is linear, so 2 MB should take milliseconds."""
        import time
        key = "a" + " " * 2_000_000 + '"b:'
        path = _write(tmp_path, V1_HEADER + key + '\n  version "1.0.0"\n')
        start = time.perf_counter()
        with pytest.raises(UnreadableManifest, match="unreadable entry key"):
            extract_yarn_lock(path)
        assert time.perf_counter() - start < 2.0


class TestV1EntryKeys:
    """How a key line splits into descriptors: quoted, unquoted, mixed."""

    @pytest.mark.parametrize("key,names", [
        ('lodash@^4.17.15, lodash@^4.17.21:', ["lodash"]),
        ('"@babel/core@^7.0.0", "@babel/core@^7.22.0":', ["@babel/core"]),
        ('"@babel/core@^7.0.0", lodash@^4.17.21:', ["@babel/core", "lodash"]),
        ('lodash@^4.17.21,lodash@^4:', ["lodash"]),            # no space after comma
        ('lodash@^4.17.21 , lodash@^4:', ["lodash"]),          # space before comma
        ('"lodash@>= 4.0.0 < 5":', ["lodash"]),                # spaces inside quotes
        ('lodash@>= 4.0.0 < 5:', ["lodash"]),                  # spaces unquoted
    ])
    def test_key_splits_into_its_descriptors(self, tmp_path, key, names):
        content = V1_HEADER + key + '\n  version "4.17.21"\n'
        got = sorted({r["package_name"] for r in extract_yarn_lock(_write(tmp_path, content))})
        assert got == sorted(names)


class TestBerry:

    def test_npm_entries_are_recorded_and_workspaces_are_not(self, tmp_path):
        records = extract_yarn_lock(_write(tmp_path, _berry(ROOT_WORKSPACE + "\n" + LODASH)))
        assert _pairs(records) == [("lodash", "4.17.21")]
        r = records[0]
        assert r["ecosystem"] == "npm"
        assert r["requirements_type"] == "resolved"
        for column in ("is_dev", "is_optional", "runs_install_script", "declared_scope"):
            assert r[column] is None, column

    def test_workspace_dependencies_are_not_called_direct(self, tmp_path):
        """A Berry workspace entry merges dependencies and devDependencies --
        measured, 385 devDependencies sat in root workspace `dependencies`. So
        "direct" would claim production for dev tooling; nothing is claimed."""
        records = extract_yarn_lock(_write(tmp_path, _berry(ROOT_WORKSPACE + "\n" + LODASH)))
        assert {r["requirements_type"] for r in records} == {"resolved"}

    @pytest.mark.parametrize("version", [6, 8, 10])
    def test_measured_metadata_versions_are_read(self, version, tmp_path):
        records = extract_yarn_lock(_write(tmp_path, _berry(LODASH, version=version)))
        assert _pairs(records) == [("lodash", "4.17.21")]

    def test_patch_is_unwrapped_to_the_npm_version(self, tmp_path):
        """`patch:` wraps an npm descriptor, URL-encoded. The package installed
        is still that npm package at that version."""
        entry = '''\
"fsevents@patch:fsevents@npm%3A^2.3.3#optional!builtin<compat/fsevents>":
  version: 2.3.3
  resolution: "fsevents@patch:fsevents@npm%3A2.3.3#optional!builtin<compat/fsevents>::version=2.3.3&hash=df0bf1"
  languageName: node
  linkType: hard
'''
        assert _pairs(extract_yarn_lock(_write(tmp_path, _berry(entry)))) == [
            ("fsevents", "2.3.3")]

    def test_link_and_portal_entries_are_not_packages(self, tmp_path):
        entries = '''\
"helper@link:./helper::locator=app%40workspace%3A.":
  version: 0.0.0-use.local
  resolution: "helper@link:./helper::locator=app%40workspace%3A."
  languageName: node
  linkType: soft

"tool@portal:../tool::locator=app%40workspace%3A.":
  version: 0.0.0-use.local
  resolution: "tool@portal:../tool::locator=app%40workspace%3A."
  languageName: node
  linkType: soft
'''
        assert extract_yarn_lock(_write(tmp_path, _berry(entries))) == []

    def test_a_local_protocol_that_is_hard_linked_is_still_recorded(self, tmp_path):
        """All 317 real local entries are `linkType: soft`. A hard-linked one
        was copied in like a package, so the protocol alone must not hide it."""
        entry = '''\
"evil-pkg@workspace:vendor/evil":
  version: 6.6.6
  resolution: "evil-pkg@workspace:vendor/evil"
  languageName: node
  linkType: hard
'''
        assert _pairs(extract_yarn_lock(_write(tmp_path, _berry(entry)))) == [
            ("evil-pkg", "6.6.6")]

    def test_alias_records_alias_and_target(self, tmp_path):
        entry = '''\
"string-width-cjs@npm:string-width@^4.2.0":
  version: 4.2.3
  resolution: "string-width@npm:4.2.3"
  languageName: node
  linkType: hard
'''
        assert _pairs(extract_yarn_lock(_write(tmp_path, _berry(entry)))) == [
            ("string-width", "4.2.3"),
            ("string-width-cjs", "4.2.3"),
        ]

    def test_version_and_resolution_that_disagree_are_both_recorded(self, tmp_path):
        """Measured: they agree on all 12,907 real npm entries."""
        entry = '''\
"lodash@npm:^4.17.21":
  version: 4.17.21
  resolution: "lodash@npm:4.17.20"
  languageName: node
  linkType: hard
'''
        assert _pairs(extract_yarn_lock(_write(tmp_path, _berry(entry)))) == [
            ("lodash", "4.17.20"),
            ("lodash", "4.17.21"),
        ]

    def test_version_yaml_reads_as_a_number_is_not_mangled(self, tmp_path):
        """`version: 1.10` is the float 1.1 to YAML. The resolution string is
        exact, so it is the source, and a non-string `version` is not used."""
        entry = '''\
"tiny@npm:^1.10":
  version: 1.10
  resolution: "tiny@npm:1.10"
  languageName: node
  linkType: hard
'''
        assert _pairs(extract_yarn_lock(_write(tmp_path, _berry(entry)))) == [
            ("tiny", "1.10")]

    def test_metadata_only_is_genuinely_empty(self, tmp_path):
        assert extract_yarn_lock(_write(tmp_path, _berry(""))) == []

    def test_workspace_only_is_genuinely_empty(self, tmp_path):
        """The real v6 file on the estate is exactly this."""
        assert extract_yarn_lock(_write(tmp_path, _berry(ROOT_WORKSPACE, version=6))) == []


class TestBerryUnreadable:

    @pytest.mark.parametrize("version", ["4", "9", "11", "'10'x", "true", "[]"])
    def test_unmeasured_metadata_version_raises(self, version, tmp_path):
        """Only 6, 8 and 10 have been measured. Berry has no published format
        spec, so a version nobody has looked at is refused rather than guessed
        at -- the same loud choice as the pnpm parser."""
        with pytest.raises(UnreadableManifest):
            extract_yarn_lock(_write(tmp_path, _berry(LODASH, version=version)))

    def test_metadata_without_version_raises(self, tmp_path):
        content = "__metadata:\n  cacheKey: 10c0\n\n" + LODASH
        with pytest.raises(UnreadableManifest):
            extract_yarn_lock(_write(tmp_path, content))

    def test_entry_that_is_not_a_mapping_raises(self, tmp_path):
        with pytest.raises(UnreadableManifest):
            extract_yarn_lock(_write(tmp_path, _berry('"lodash@npm:^4": nonsense\n')))

    def test_entry_without_resolution_raises(self, tmp_path):
        """Measured: all 13,273 real Berry entries carry `resolution`."""
        entry = '"lodash@npm:^4.17.21":\n  version: 4.17.21\n  linkType: hard\n'
        with pytest.raises(UnreadableManifest):
            extract_yarn_lock(_write(tmp_path, _berry(entry)))

    def test_invalid_yaml_raises(self, tmp_path):
        with pytest.raises(UnreadableManifest):
            extract_yarn_lock(_write(tmp_path, _berry('"lodash@npm:^4":\n  version: [\n')))


class TestUnreadable:

    def test_missing_file(self, tmp_path):
        with pytest.raises(UnreadableManifest):
            extract_yarn_lock(str(tmp_path / "nope.lock"))

    def test_directory(self, tmp_path):
        with pytest.raises(UnreadableManifest):
            extract_yarn_lock(str(tmp_path))

    def test_binary_content(self, tmp_path):
        with pytest.raises(UnreadableManifest):
            extract_yarn_lock(_write_bytes(tmp_path, b"\xff\xfe\x00\x01\x02\x03"))

    def test_empty_file(self, tmp_path):
        """yarn always writes a header, so a 0-byte file is not a lockfile."""
        with pytest.raises(UnreadableManifest):
            extract_yarn_lock(_write(tmp_path, ""))

    def test_comment_only_file_raises(self, tmp_path):
        """One real yarn.lock is a test fixture holding only a comment. Neither
        format's header is there, so nothing can be concluded about the
        repository's dependencies from it -- the pnpm parser makes the same
        call for a 0-byte pnpm-lock.yaml."""
        with pytest.raises(UnreadableManifest):
            extract_yarn_lock(_write(tmp_path, "# this file should be ignored\n"))

    def test_yaml_without_metadata_raises(self, tmp_path):
        """Not v1 (no header) and not Berry (no __metadata)."""
        with pytest.raises(UnreadableManifest):
            extract_yarn_lock(_write(tmp_path, LODASH))


class TestRegistry:

    def test_yarn_lock_is_supported_and_resolves_here(self):
        from kospex.extractors.registry import classify, resolve_parser
        result = classify("yarn.lock")
        assert result.supported
        assert set(result.scanners) == {"sca", "osi"}
        assert resolve_parser(result.extractor) is extract_yarn_lock
